import{anatomicalHeartFigure}from './heart-anatomy.js?v=20261023-physicscomplete01';
import{circuit,gasSnapshot}from './circulation-models.js?v=20261023-physicscomplete01';
const text=(x,y,t,s=16)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-size="${s}">${t}</text>`;
export const circSvg=(label,body)=>`<svg class="shell-diagram circ-diagram" viewBox="0 0 480 350" role="img" aria-label="${label}">${body}</svg>`;
export const heartFigure=anatomicalHeartFigure;
export function circuitFigure(index=0){const s=circuit[Math.min(10,Math.max(0,index))];return circSvg('Double circulation; selected '+s.name,`<rect x="160" y="15" width="160" height="60" rx="20" stroke="#f8f6f2" fill="#91a5b3" fill-opacity=".25"/><rect x="160" y="270" width="160" height="60" rx="20" stroke="#f8f6f2" fill="#ed8b78" fill-opacity=".25"/><rect x="160" y="135" width="160" height="70" rx="20" stroke="#f8f6f2" fill="#b7c8d6" fill-opacity=".25"/><path d="M165 170Q65 100 165 45M315 45Q415 100 315 170M315 180Q415 250 315 300M165 300Q65 250 165 180" fill="none" stroke="#f8f6f2" stroke-width="6"/>`+'<path d="M100 95l-9 17h18ZM380 112l-9 -17h18ZM100 232l-9 17h18ZM380 249l-9 -17h18Z" fill="#ed8b78"/>'+text(240,52,'Lungs')+text(240,178,'Heart')+text(240,307,'Body')+text(240,111,s.name,16)+text(240,244,s.oxygen,15));}
export function vesselFigure(w={}){const outer=w.wall==='thick'?90:w.wall==='one'?57:65,inner=w.lumen==='large'?55:40;return circSvg('Schematic vessel cross-section with selected wall and lumen',`<circle cx="240" cy="145" r="${outer}" fill="#ed8b78"/><circle cx="240" cy="145" r="${inner}" fill="#182e44" stroke="#f8f6f2"/>${w.valve==='yes'?'<path d="M210 160L240 125L270 160" fill="none" stroke="#f8f6f2" stroke-width="6"/>':''}`+text(240,265,'Lumen: '+(w.lumen==='large'?'large':'relatively narrow'))+text(240,300,'Wall: '+(w.wall==='one'?'one cell layer':w.wall||'not selected')));}
export function bloodFigure(component='red',labelled=true,on=true){const colour=labelled?'#f8f6f2':'currentColor',shape=component==='red'?`<ellipse cx="240" cy="155" rx="90" ry="65" fill="${labelled&&!on?'#b7c8d6':'#ed8b78'}" stroke="${colour}" stroke-width="3"/><ellipse cx="240" cy="155" rx="40" ry="26" fill="#f8d9ce"/>`:component==='white'?`<circle cx="240" cy="155" r="76" fill="#d4dfe7" stroke="${colour}" stroke-width="3"/><path d="M200 125Q230 95 245 135Q285 110 280 155Q310 185 260 195Q225 220 220 175Q180 165 200 125" fill="#71808c"/>`:component==='platelet'?Array.from({length:5},(_,i)=>`<path d="M${130+i*42} ${135+i%2*30}l22 -14l16 24l-27 14Z" fill="#ca715f" stroke="${colour}"/>`).join(''):`<path d="M240 55Q340 180 300 225Q240 290 180 225Q140 180 240 55" fill="#d9bd7d" fill-opacity=".5" stroke="${colour}"/>`;return circSvg(labelled?'Schematic blood component, '+(on?'function present':'feature removed'):({red:'Unlabelled flattened disc with central pale area; no nucleus shown',white:'Unlabelled rounded cell containing a lobed central structure',platelet:'Unlabelled small irregular fragments; separately enlarged'}[component]||'Unlabelled blood component schematic'),shape+(labelled&&component==='white'?`<circle cx="${on?260:365}" cy="155" r="12" fill="#ca715f"/>`:labelled&&component==='platelet'?`<path d="M60 240H210M270 240H420" stroke="#f8f6f2" stroke-width="8"/>${on?'<path d="M210 240H270" stroke="#ca715f" stroke-width="15"/>':''}`:'')+(labelled?text(240,315,on?'Feature/function present':'Counterfactual feature removed'):`<text x="240" y="315" text-anchor="middle" fill="currentColor" font-size="14">Schematic · separately enlarged</text>`));}
export function lungFigure(w={}){if(w.exchange){const s=gasSnapshot(w.step);return circSvg('Illustrative gas diffusion between alveolar air and blood',`<rect x="25" y="50" width="200" height="205" rx="25" fill="#91a5b3" fill-opacity=".2"/><rect x="255" y="50" width="200" height="205" rx="25" fill="#ed8b78" fill-opacity=".2"/><path d="M235 50V255M245 50V255" stroke="#f8f6f2" stroke-width="3"/>`+text(125,30,'Alveolar air')+text(355,30,'Blood')+text(125,120,'O₂ units: '+s.oxygen.air)+text(355,120,'O₂ units: '+s.oxygen.blood)+text(125,195,'CO₂ units: '+s.carbon.air)+text(355,195,'CO₂ units: '+s.carbon.blood)+text(240,300,'O₂ → blood · CO₂ → alveolar air',16));}return circSvg('Schematic trachea, bronchi and alveoli with capillary network',`<path d="M240 20V110M240 110L135 180M240 110L345 180" stroke="#d4dfe7" stroke-width="22" fill="none"/>`+[[110,225],[160,240],[320,240],[370,225]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="37" fill="#91a5b3" fill-opacity=".3" stroke="#f8f6f2" stroke-width="3"/><path d="M${x-42} ${y+8}q42 80 84 0" stroke="#ed8b78" stroke-width="8" fill="none"/>`).join('')+text(320,60,'Trachea')+text(240,155,'Bronchi')+text(240,325,'Alveoli surrounded by capillaries',15));}

export function valveFigure(valve='working',direction='forward',tested=false){const reverse=direction==='reverse',blocked=valve==='working'&&reverse;return circSvg('Schematic valve comparison',`<path d="M35 100H445M35 250H445" stroke="#d4dfe7" stroke-width="8"/><path d="M240 100L${blocked?240:285} 175L240 250" stroke="#f8f6f2" stroke-width="8" fill="none"/><path d="M${reverse?410:70} 175H${reverse?275:390}" stroke="#ed8b78" stroke-width="8"/><path d="${reverse?'M275 175l25 -15v30Z':'M390 175l-25 -15v30Z'}" fill="#ed8b78"/>`+text(240,45,valve==='working'?'Working valve':'Leaky valve counterfactual')+text(240,310,tested?(blocked?'Attempted backflow blocked':reverse?'Backflow occurs through the leak':'Forward flow allowed'):'Choose a pressure direction, then test',15));}
